"""Build the local Chrome review for nine dogs and companion-shape experiments."""
from pathlib import Path
import json
ROOT=Path(__file__).resolve().parents[1];OUT=ROOT/'design/nine-dog-review'
data=json.loads((OUT/'options.json').read_text())
# Anchor letters to the original empty pockets so companion choices retain IDs.
from shapely.geometry import Polygon
from shapely.ops import polylabel
for layout_key in {o['layout'] for o in data}:
    base=next(o for o in data if o['layout']==layout_key and o['companion_selection']=='none')
    regions=[Polygon(p['points'],p['holes']) for p in base['pieces'] if p['category']=='remainder']
    regions.sort(key=lambda p:(round(p.representative_point().y/10),p.representative_point().x))
    for o in (o for o in data if o['layout']==layout_key):
        for piece in (p for p in o['pieces'] if p['category']=='remainder'):
            polygon=Polygon(piece['points'],piece['holes'])
            owner=max(range(len(regions)),key=lambda i:regions[i].intersection(polygon).area)
            n=owner+1;letter=''
            while n:
                n,r=divmod(n-1,26);letter=chr(65+r)+letter
            piece['negative_id']=letter
            piece['label_point']=list(polylabel(polygon,tolerance=.1).coords)[0]
refs=[('birds-2.jpg','Curved bird profiles','One animal’s neck becomes its neighbor’s wing.'),('birds.jpg','Alternating birds','Shared curves exchange convex and concave forms.'),('cats-and-birds.png','Cats + birds','Negative space becomes a second recognizable animal.'),('cats-and-dogs-2.png','Seated cats + dogs','Different proportions; faces supply much of the recognition.'),('cats-and-dogs.jpg','Slender cats + dogs','Unequal profiles interlock through heads and legs.'),('elephants.png','Elephants','Broad bodies pack together through trunks and backs.'),('fish-and-birds.jpg','Fish + birds','A second species can fill a different aspect ratio.'),('fish.png','Rotating fish','Orientation changes help tails fill surrounding space.'),('kangaroos.png','Kangaroos','Varied poses trade tail, leg, and body space.')]
gallery=''.join(f'<figure><a href="../../inspiration/{f}"><img src="../../inspiration/{f}" alt="{title} inspiration image"></a><figcaption><strong>{title}</strong><br>{desc}<br><small>{f}</small></figcaption></figure>' for f,title,desc in refs)
html='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Tofu — nine dogs and companion shapes</title>
<style>
*{box-sizing:border-box}body{margin:0;background:#faf7f0;color:#342e25;font:16px/1.5 system-ui,sans-serif}main{max-width:1300px;margin:auto;padding:36px}header{border-bottom:1px solid #d8cfc0;padding-bottom:22px;margin-bottom:24px}h1{font-size:38px;line-height:1.12;margin:10px 0}h2{font-size:20px;margin:0 0 14px}p{max-width:890px}.eyebrow{font-size:12px;letter-spacing:2px;color:#756849}.controls{display:flex;flex-wrap:wrap;gap:10px;margin-bottom:14px}button{font:inherit;border:1px solid #b9ad99;border-radius:25px;padding:9px 16px;background:transparent;cursor:pointer}button[aria-pressed=true]{background:#385447;border-color:#385447;color:white}.companions{display:flex;align-items:center;gap:8px;flex-wrap:wrap;margin-bottom:20px;font-size:14px}.companions[hidden]{display:none}.companions select{font:inherit;padding:8px 12px;border:1px solid #b9ad99;border-radius:8px;background:#faf7f0}.theme-grid{display:grid;grid-template-columns:repeat(4,1fr);gap:20px}.theme-grid svg{width:100%;height:100px}.theme-grid figure{font-size:14px}.theme-grid figcaption{margin-top:8px}.main-grid{display:grid;grid-template-columns:minmax(0,1fr) 285px;gap:36px}.drawing{width:100%;display:block;max-height:630px}.drawing path[role=button]{cursor:pointer}.drawing path.selected{stroke:#28513d;stroke-width:.7}.label-controls{display:flex;gap:24px;flex-wrap:wrap;margin:0 0 20px;font-size:14px}.label-controls label{cursor:pointer}.label-controls input{accent-color:#385447;margin-right:6px}.hide-positive .positive-label,.hide-negative .negative-label{display:none}.dog-id{pointer-events:none;font-size:3px;font-weight:700;fill:#294a3c;paint-order:stroke;stroke:#faf7f0;stroke-width:1px;stroke-linejoin:round}.drawing path[role=button]:hover,.drawing path[role=button]:focus{stroke:#28513d;stroke-width:.8;outline:none}.isolated{width:100%;height:220px;display:block}.caption{font-size:13px;color:#736855}.line{border-top:1px solid #d8cfc0;padding-top:18px;margin-top:18px}.metrics{display:flex;gap:24px;flex-wrap:wrap;font-size:14px}.number{font-size:26px;line-height:1.1}.pill-label{font-size:12px;text-transform:uppercase;letter-spacing:1px}.detail{min-height:66px}.remainder{color:#736855}.summary{margin:20px 0;font-size:14px}.notes{display:grid;grid-template-columns:1fr 1fr;gap:35px}a{color:#315c44}.gallery{display:grid;grid-template-columns:repeat(3,1fr);gap:24px;margin-top:20px}figure{margin:0}.gallery img{width:100%;height:240px;object-fit:contain;background:#f1eadf}.gallery figcaption{font-size:14px;margin-top:10px}summary{cursor:pointer;font-weight:600}.legend{font-size:13px;color:#736855;margin-top:8px}.label{font-size:14px;color:#736855}footer{margin-top:30px}@media(max-width:800px){main{padding:20px}.main-grid{grid-template-columns:1fr}.isolated{max-width:260px}.notes{grid-template-columns:1fr}.gallery{grid-template-columns:1fr 1fr}h1{font-size:30px}}
</style>
<main><header><div class="eyebrow">TOFU / A, DEVELOPED FURTHER</div><h1>Nine dogs / 3 × 3 — CAD baseline.</h1><p>The original nine dogs / 3 × 3 layout is the selected design. The varied-profile and companion studies are earlier explorations.</p></header>
<p><a href="../../cad/nine-dogs-3x3/index.html">Open the CadQuery cutter model, renders, and downloads</a></p><div class="controls" aria-label="Dog layout"><button data-layout="a6" aria-pressed="false">A · original six</button><button data-layout="a9" aria-pressed="true">A · nine dogs / 3 × 3</button><button data-layout="varied" aria-pressed="false">Nine · varied profiles</button></div>
<div class="companions" id="companions"><label for="companion-select">Gap shapes:</label><select id="companion-select" aria-label="Gap shapes"></select></div>
<div class="label-controls" role="group" aria-label="Label visibility"><label><input id="positive-labels" type="checkbox" checked> Positive-space labels</label><label><input id="negative-labels" type="checkbox" checked> Negative-space labels</label></div>
<div class="main-grid"><section><h2 id="title"></h2><svg class="drawing" id="layout" role="group" aria-label="Tofu cutting layout in a 120 by 100 millimetre rectangle" viewBox="-2 -2 124 110"></svg><div class="legend">Tan: dogs · green: bones · blue: fish · gray: remaining tofu. Dogs: 1–9 · negative spaces: letters. Hover or click either for details. IDs stay consistent across gap-shape choices.</div></section><aside><h2 id="isolated-title">Plain cut silhouette</h2><svg class="isolated" id="isolated" role="img" aria-label="Selected cutout without decorative eye or ear marks"></svg><p id="detail" class="detail" aria-live="polite"></p><div class="line metrics"><div><div class="number" id="dogs"></div><div>dogs</div></div><div><div class="number" id="extras"></div><div>companions</div></div><div class="remainder"><div class="number" id="remainder"></div><div>remainder</div></div></div><p class="caption">Percent of the sheet’s plan area. Colored pieces are proposed silhouettes; recognition and physical cutting remain to be assessed.</p><p id="context" class="summary"></p></aside></div>
<div class="line notes"><section><h2>Varied profiles, refined</h2><p><a href="../varied-refinement/neck-face-comparison.png">Tail-to-leg and face: before and after</a></p><p>Small exposed notches are filled and pointed outer tips rounded. IDs 1–9 are fixed to the same dogs across every gap-shape option. Numbers are review labels, not cut lines.</p><a href="../varied-refinement/comparison.png">Compare the varied profiles before and after</a><h2>Smoother shared curves</h2><p>The small bump where a foot joins the next dog’s back has been flattened. Shared curves move together so this correction does not open gaps between dogs. The broader perimeter variants also receive a shared-curve smoothing pass.</p><p>This smooths the silhouette in plan view. The eventual blade still needs a sharp cutting edge.</p><a href="../smoothing-review/smoothing-comparison.png">Inspect the before-and-after contour</a></section><section><h2>Bones now work with the original six</h2><p>Choose <strong>A · original six</strong>, then <strong>Bones</strong>. Companion choices are available in all three layouts; counts and coverage update for the selected option.</p><p>The additional shapes are experimental fitted outlines. Gray strips remain counted as remainder, and a familiar shape name is not proof that its tofu cutout will read clearly.</p></section></div>
<section class="line"><h2>Dog-themed gap shapes</h2><p class="caption">Search terms: dog-themed cookie cutters, paw, kennel, hydrant, bowl, collar tag, fetch ball, flying disc. Sources: <a href="https://www.k9cakery.com/mini-dog-theme-cookie-cutters-5-dog-related-shapes/">K9Cakery’s dog-themed shapes</a> and <a href="https://www.kongcompany.com/dog-toys/">KONG’s dog toys</a>. The sketches below are our own geometric studies.</p><div class="theme-grid" id="theme-grid"></div><p class="caption">A joined paw stays one piece. Balls and bowls depend on the dog theme for context. Collars, tags, and flying discs remain ideas; their outlines become generic without drawn details or extra holes.</p></section>
<p class="caption">Zero-width outline studies. Companion candidates below 120 mm² are excluded; bone shafts must be at least 4 mm wide. These provisional filters do not validate cutting, release, or minimum feature widths of the other shapes. Fitted companion loops still require structural supports in the final cutter.</p>
<section class="line"><details id="inspiration"><summary>All nine inspiration images — opened and reviewed</summary><p class="caption">The mixed-species examples informed the companion studies. Varied silhouettes and shared boundaries guide the dog layouts.</p><div class="gallery">__GALLERY__</div></details></section>
<footer><a href="comparison.svg">Three-layout comparison</a> · <a href="companions.png">Six dogs: bones versus paws</a> · <a href="../VARIED_REFINEMENT.md">Design notes</a> · <a href="../INSPIRATION_REVIEW.md">Inspiration findings</a></footer></main>
<script>
const options=__DATA__, templates=__TEMPLATES__;let layout='a9',comp='none';const ns='http://www.w3.org/2000/svg';const root=document.getElementById('layout');const colors={dog:['#e1b780','#d1a26b','#edc896'],bone:['#88b2a1'],fish:['#83adc1'],paw:['#ad96b7'],ball:['#dca568'],house:['#c28d7e'],hydrant:['#bd7c76'],bowl:['#94aabc'],remainder:['#e4dfd6']};
const labels={bowl_d:'Bowl D + longer muzzle 1',none:'None',bones:'Bones',fish:'Fish (earlier idea)',paws:'Joined paws',balls:'Fetch balls',houses:'Doghouses',hydrants:'Fire hydrants',bowls:'Bowls'};
function svgpath(s){let p=document.createElementNS(ns,'path');const rings=[s.points,...(s.holes||[])];p.setAttribute('d',rings.map(r=>'M'+r.map(v=>v.join(',')).join('L')+'Z').join(''));p.setAttribute('fill-rule','evenodd');return p;}
function inspect(s,index){root.querySelectorAll('path[data-piece-key]').forEach(p=>p.classList.toggle('selected',p.dataset.pieceKey===s.category+':'+index));const svg=document.getElementById('isolated');svg.replaceChildren();const p=svgpath(s);p.setAttribute('fill',colors[s.category][0]);p.setAttribute('stroke','#64523c');p.setAttribute('stroke-width','.35');svg.append(p);const xs=s.points.map(v=>v[0]),ys=s.points.map(v=>v[1]),x=Math.min(...xs),y=Math.min(...ys),w=Math.max(...xs)-x,h=Math.max(...ys)-y;svg.setAttribute('viewBox',[x-3,y-3,w+6,h+6].join(' '));document.getElementById('isolated-title').textContent=s.category==='dog'?'Dog '+index+' · profile':s.category==='remainder'?'Negative space '+index:s.feedback_id?(s.category==='bowl'?'Bowl ':'Doghouse ')+index:'Plain '+s.category+' silhouette';document.getElementById('detail').textContent=(s.category==='remainder'?'Negative space':s.category[0].toUpperCase()+s.category.slice(1))+' '+index+' · '+w.toFixed(1)+' × '+h.toFixed(1)+' mm · '+s.area_mm2.toFixed(0)+' mm²';}
function draw(){if(!options.some(v=>v.layout===layout&&v.companion_selection===comp))comp='none';const o=options.find(v=>v.layout===layout&&v.companion_selection===comp);const id=o.id;root.replaceChildren();let counts={dog:0,bone:0,fish:0,paw:0,ball:0,house:0,hydrant:0,bowl:0,remainder:0},first=null;o.pieces.forEach(s=>{const i=counts[s.category]++;const p=svgpath(s);p.setAttribute('fill',colors[s.category][i%colors[s.category].length]);p.setAttribute('stroke','#695941');p.setAttribute('stroke-width','.22');{p.setAttribute('role','button');p.setAttribute('tabindex','0');const profileId=s.feedback_id||s.negative_id||s.profile_id||i+1;p.dataset.pieceKey=s.category+':'+profileId;p.setAttribute('aria-label','Inspect '+(s.category==='remainder'?'negative space':s.category)+' '+profileId);const tip=document.createElementNS(ns,'title');tip.textContent=s.category==='dog'?'Dog '+profileId:'Inspect '+s.category+' '+profileId;p.append(tip);if(s.category==='dog'||s.category==='remainder'||s.feedback_id){p.dataset.dogId=profileId;p.onmouseenter=()=>inspect(s,profileId);p.onfocus=()=>inspect(s,profileId);}p.onclick=()=>inspect(s,profileId);p.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();inspect(s,profileId)}};if(!first)first=s;}root.append(p)});o.pieces.filter(s=>s.category==='dog'||s.category==='remainder'||s.feedback_id).forEach(s=>{const label=document.createElementNS(ns,'text');label.setAttribute('x',s.label_point[0]);label.setAttribute('y',s.label_point[1]);label.setAttribute('text-anchor','middle');label.setAttribute('dominant-baseline','middle');label.setAttribute('class','dog-id '+(s.category==='remainder'?'negative-label':'positive-label'));label.textContent=s.feedback_id||s.negative_id||s.profile_id;if(s.category==='remainder'){label.style.fill='#685479';if(s.area_mm2<4){const lx=s.label_point[0]>115?122:s.label_point[0];const ly=s.label_point[0]>115?s.label_point[1]:s.label_point[1]-4;label.setAttribute('x',lx);label.setAttribute('y',ly);const leader=document.createElementNS(ns,'line');leader.setAttribute('x1',s.label_point[0]);leader.setAttribute('y1',s.label_point[1]);leader.setAttribute('x2',lx);leader.setAttribute('y2',ly+1);leader.setAttribute('stroke','#685479');leader.setAttribute('stroke-width','.15');leader.setAttribute('class','negative-label');leader.style.pointerEvents='none';root.append(leader);}}root.append(label)});let text=document.createElementNS(ns,'text');text.setAttribute('x','60');text.setAttribute('y','106');text.setAttribute('text-anchor','middle');text.setAttribute('font-size','3');text.textContent='120 × 100 mm';root.append(text);document.getElementById('title').textContent=o.title;document.getElementById('dogs').textContent=o.dog_area_percent+'%';document.getElementById('extras').textContent=o.companion_area_percent+'%';document.getElementById('remainder').textContent=o.remainder_percent+'%';document.getElementById('context').textContent=o.dogs+' dogs'+(o.companions?' + '+o.companions+' '+labels[comp].toLowerCase():'')+'. '+(comp!=='none'&&!o.companions?'No candidate passed the current size filter. ':'')+(comp==='corner_house'?'Doghouse C fills the whole upper-right pocket; dog 3’s tail forms its open doorway.':'All surrounding strips remain included in the gray remainder.');
const select=document.getElementById('companion-select');select.replaceChildren();options.filter(v=>v.layout===layout).forEach(v=>{const el=document.createElement('option');el.value=v.companion_selection;el.textContent=labels[v.companion_selection]+(v.companion_selection==='none'?'':' · '+v.companions+' fit');select.append(el)});select.value=comp;document.querySelectorAll('[data-layout]').forEach(b=>b.setAttribute('aria-pressed',b.dataset.layout===layout));const companion=o.pieces.find(s=>s.feedback_id);inspect(companion||first,companion?companion.feedback_id:1);}
document.getElementById('positive-labels').onchange=e=>root.classList.toggle('hide-positive',!e.target.checked);document.getElementById('negative-labels').onchange=e=>root.classList.toggle('hide-negative',!e.target.checked);
document.querySelectorAll('[data-layout]').forEach(b=>b.onclick=()=>{layout=b.dataset.layout;draw()});document.getElementById('companion-select').onchange=e=>{comp=e.target.value;draw()};draw();
const themeNotes={bones:'Preferred dog theme; rounded lobes and a substantial shaft.',paws:'Connected toe bumps, not five separate tiny pads.',balls:'A simple circle; reads as a ball within the theme.',houses:'A roof and open doorway distinguish the kennel outline.',hydrants:'A rounded dome, side outlets, and broad base.',bowls:'A low, broad shape for flatter pockets.',fish:'Previous mixed-animal idea, retained for comparison.'};Object.entries(templates).forEach(([key,t])=>{const figure=document.createElement('figure'),svg=document.createElementNS(ns,'svg');svg.setAttribute('viewBox','-1.4 -1.4 2.8 2.8');svg.setAttribute('role','img');svg.setAttribute('aria-label',labels[key]+' concept outline');const p=svgpath({points:t.points});p.setAttribute('fill',colors[t.kind][0]);svg.append(p);const caption=document.createElement('figcaption');const strong=document.createElement('strong');strong.textContent=labels[key];caption.append(strong,document.createElement('br'),themeNotes[key]);figure.append(svg,caption);document.getElementById('theme-grid').append(figure)});
</script></html>'''
(OUT/'index.html').write_text(html.replace('__DATA__',json.dumps(data)).replace('__TEMPLATES__',(OUT/'theme-templates.json').read_text()).replace('__GALLERY__',gallery))
print(OUT/'index.html')
